package com.aaliyun.leadnews.common.security;
import org.junit.jupiter.api.Test;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.time.Duration;import static org.assertj.core.api.Assertions.*;
class AuthenticationFoundationTest {private static final String HASH="$2a$10$72y79aQx6pCuCdwwCbyE4OT8ENZpEajFAS6LrwNkHmwUGKA77P9uu";@Test void bcryptAcceptsDevelopmentPassword(){assertThat(new BCryptPasswordEncoder().matches("password",HASH)).isTrue();}@Test void bcryptRejectsIllegalPassword(){assertThat(new BCryptPasswordEncoder().matches("wrong-password",HASH)).isFalse();}@Test void realLoginStyleJwtContainsIdentityAndType(){JwtTokenService s=new JwtTokenService("stage4-test-secret-at-least-32-bytes-long");String token=s.createToken(7,"ADMIN",Duration.ofMinutes(5));assertThat(s.parse(token).userId()).isEqualTo(7L);assertThat(s.parse(token).clientType()).isEqualTo("ADMIN");}}
